const PYTHON_FILES = {"svr_roughness/__init__.py": "\"\"\"Surface roughness analysis for scanner point clouds.\"\"\"\n\nfrom ._display_grid import svr_map\nfrom ._version import version as __version__\nfrom .analyze import (\n    analyze_file,\n    analyze_ply,\n    analyze_points,\n    compute_roughness,\n    compute_roughness_from_ply,\n)\nfrom .config import RoughnessConfig\nfrom .io import load_ascii_ply, load_delimited, load_obj, load_pcd, load_ply, load_points, load_stl_vertices\nfrom .result import PlaneFit, RoughnessGrid, RoughnessResult, format_report\n\n__all__ = [\n    \"PlaneFit\",\n    \"RoughnessConfig\",\n    \"RoughnessGrid\",\n    \"RoughnessResult\",\n    \"__version__\",\n    \"analyze_file\",\n    \"analyze_ply\",\n    \"analyze_points\",\n    \"compute_roughness\",\n    \"compute_roughness_from_ply\",\n    \"format_report\",\n    \"load_ascii_ply\",\n    \"load_delimited\",\n    \"load_obj\",\n    \"load_pcd\",\n    \"load_ply\",\n    \"load_points\",\n    \"load_stl_vertices\",\n    \"svr_map\",\n]\n", "svr_roughness/__main__.py": "from __future__ import annotations\n\nimport argparse\nimport sys\nfrom pathlib import Path\n\nfrom .analyze import analyze_file\nfrom .config import RoughnessConfig\nfrom .result import format_report\n\n\ndef main() -> None:\n    if hasattr(sys.stdout, \"reconfigure\"):\n        try:\n            sys.stdout.reconfigure(encoding=\"utf-8\")\n        except Exception:\n            pass\n\n    parser = argparse.ArgumentParser(description=\"Calculate surface roughness from a point-cloud file.\")\n    parser.add_argument(\"input\", type=Path, help=\"Input PLY, PCD, STL, OBJ, CSV, XYZ, TXT, TSV, NPY, or NPZ file\")\n    parser.add_argument(\"--grid-mm\", type=float, default=0.20, help=\"Grid pitch / downsample in mm (default: 0.20)\")\n    parser.add_argument(\"--short-cutoff-mm\", type=float, default=1.0, help=\"Short cutoff lambda_s in mm (default: 1.0)\")\n    parser.add_argument(\"--long-cutoff-mm\", type=float, default=25.0, help=\"Long cutoff lambda_c in mm (default: 25.0)\")\n    parser.add_argument(\n        \"--gaussian-mesh\", action=\"store_true\", default=True, help=\"Enforce ISO 16610-61 Gaussian filtration\"\n    )\n    parser.add_argument(\"--metrics-out\", type=Path)\n    parser.add_argument(\"--grid-out\", type=Path)\n    args = parser.parse_args()\n\n    result = analyze_file(\n        args.input,\n        RoughnessConfig(\n            grid_mm=args.grid_mm,\n            short_cutoff_mm=args.short_cutoff_mm,\n            long_cutoff_mm=args.long_cutoff_mm,\n            gaussian_mesh=args.gaussian_mesh,\n        ),\n    )\n    print(format_report(result))\n    if args.metrics_out:\n        result.save_metrics_json(args.metrics_out)\n    if args.grid_out:\n        result.save_grid_npz(args.grid_out)\n\n\nif __name__ == \"__main__\":\n    main()\n\n", "svr_roughness/_display_grid.py": "from __future__ import annotations\n\nimport numpy as np\nimport numpy.typing as npt\n\nfrom .config import RoughnessConfig\nfrom .result import BoolArray, FloatArray, PlaneFit\n\n\ndef fit_plane_basis(points: npt.ArrayLike) -> PlaneFit:\n    \"\"\"Fit a plane to the point cloud and return a local coordinate system.\n\n    The X-axis is the projection of global X onto the fitted plane, preserving\n    the original scan orientation rather than rotating to PCA axes.\n    \"\"\"\n    points_array = np.asarray(points, dtype=np.float64)\n    centroid = points_array.mean(axis=0)\n    centered = points_array - centroid\n    # Fast 3x3 covariance eigen-decomposition (O(N) single pass vs O(N*3^2) full SVD)\n    cov = (centered.T @ centered) / max(len(points_array) - 1, 1)\n    _, eigvecs = np.linalg.eigh(cov)\n    normal = eigvecs[:, 0]\n    if normal[2] < 0:\n        normal = -normal\n    normal /= np.linalg.norm(normal)\n\n    # Project global X-axis onto the fitted plane to keep the original scan orientation\n    # instead of rotating based on point distribution variance (PCA).\n    global_x = np.array([1.0, 0.0, 0.0])\n    x_axis = global_x - normal * np.dot(global_x, normal)\n    x_axis_norm = np.linalg.norm(x_axis)\n\n    if x_axis_norm < 1e-6:\n        global_y = np.array([0.0, 1.0, 0.0])\n        x_axis = global_y - normal * np.dot(global_y, normal)\n        x_axis /= np.linalg.norm(x_axis)\n    else:\n        x_axis /= x_axis_norm\n\n    y_axis = np.cross(normal, x_axis)\n    y_axis /= np.linalg.norm(y_axis)\n    coords = np.column_stack((centered @ x_axis, centered @ y_axis, centered @ normal))\n    return PlaneFit(centroid=centroid, normal=normal, x_axis=x_axis, y_axis=y_axis, coords=coords)\n\n\ndef crop_points(coords: FloatArray, config: RoughnessConfig) -> tuple[FloatArray, BoolArray]:\n    \"\"\"Crop points by percentile and/or range filters.\"\"\"\n    mask = np.ones(len(coords), dtype=bool)\n    if config.percentile_crop > 0:\n        p = config.percentile_crop\n        xlo, xhi = np.percentile(coords[:, 0], [p, 100 - p])\n        ylo, yhi = np.percentile(coords[:, 1], [p, 100 - p])\n        mask &= (coords[:, 0] >= xlo) & (coords[:, 0] <= xhi)\n        mask &= (coords[:, 1] >= ylo) & (coords[:, 1] <= yhi)\n    if config.x_range:\n        mask &= (coords[:, 0] >= config.x_range[0]) & (coords[:, 0] <= config.x_range[1])\n    if config.y_range:\n        mask &= (coords[:, 1] >= config.y_range[0]) & (coords[:, 1] <= config.y_range[1])\n    if config.z_range:\n        mask &= (coords[:, 2] >= config.z_range[0]) & (coords[:, 2] <= config.z_range[1])\n    return coords[mask], mask\n\n\ndef svr_map(\n    grid_filtered: FloatArray,\n    valid_mask: BoolArray,\n    grid_mm: float,\n    svr_points: int = 20,\n    svr_span_mm: float = 0.5,\n) -> FloatArray:\n    \"\"\"Compute local Svr variogram map (in \u00b5m) for 2D heatmap rendering.\"\"\"\n    rows, cols = grid_filtered.shape\n    output = np.full((rows, cols), np.nan, dtype=np.float64)\n    if not np.any(valid_mask) or grid_mm <= 0 or svr_span_mm <= 0:\n        return output\n\n    max_dist_mm = svr_points * svr_span_mm\n    radius_cells = int(np.ceil(max_dist_mm / grid_mm))\n\n    y_indices, x_indices = np.where(valid_mask)\n    for r, c in zip(y_indices, x_indices):\n        r_min = max(0, r - radius_cells)\n        r_max = min(rows, r + radius_cells + 1)\n        c_min = max(0, c - radius_cells)\n        c_max = min(cols, c + radius_cells + 1)\n\n        sub_grid = grid_filtered[r_min:r_max, c_min:c_max]\n        sub_valid = valid_mask[r_min:r_max, c_min:c_max]\n\n        center_val = grid_filtered[r, c]\n        sub_y, sub_x = np.ogrid[r_min - r : r_max - r, c_min - c : c_max - c]\n        dists_mm = np.sqrt(sub_y**2 + sub_x**2) * grid_mm\n\n        mask = sub_valid & (dists_mm > 0) & (dists_mm <= max_dist_mm)\n        if not np.any(mask):\n            continue\n\n        diffs_um = (center_val - sub_grid[mask]) * 1000.0\n        output[r, c] = float(np.sqrt(np.mean(diffs_um**2)))\n\n    return output\n", "svr_roughness/_version.py": "# file generated by vcs-versioning\n# don't change, don't track in version control\nfrom __future__ import annotations\n\n__all__ = [\n    \"__version__\",\n    \"__version_tuple__\",\n    \"version\",\n    \"version_tuple\",\n    \"__commit_id__\",\n    \"commit_id\",\n]\n\nversion: str\n__version__: str\n__version_tuple__: tuple[int | str, ...]\nversion_tuple: tuple[int | str, ...]\ncommit_id: str | None\n__commit_id__: str | None\n\n__version__ = version = '0.5.94.dev0+g922a7bc81.d20260908'\n__version_tuple__ = version_tuple = (0, 5, 94, 'dev0', 'g922a7bc81.d20260908')\n\n__commit_id__ = commit_id = 'g922a7bc81'\n", "svr_roughness/algorithm.py": "\"\"\"Pure-Python ASTM WK92969 Gaussian areal roughness numerical core.\n\nReplaces the legacy C++ DLL with a fully vectorized NumPy/SciPy engine.\nImplements the exact 5-stage pipeline from SurfInspect:\n1. Centering & unit adjustment\n2. Voxel grid downsampling (fast 1D key-based grouping)\n3. PCA best-fit plane alignment (matching PCL PCA convention)\n4. 2.5D elevation grid rasterization with boundary cropping & hole filling\n5. Dual-pass ISO 16610-61 Gaussian filtration (alpha=0.4697)\n6. 2D FFT autocorrelation variogram (Sa, Sq, Svr) and local Svr dispersion map\n\"\"\"\n\nfrom __future__ import annotations\n\nimport math\nfrom typing import NamedTuple\n\nimport numpy as np\nfrom numpy.lib.stride_tricks import sliding_window_view\n\n\nclass PurePythonResult(NamedTuple):\n    sa_um: float\n    sq_um: float\n    svr_um: float\n    processed_points: int\n    variogram_bins_um: np.ndarray\n    variogram_counts: np.ndarray\n    surface_distances_mm: np.ndarray\n    grid_width: int\n    grid_height: int\n    grid_origin_mm: np.ndarray\n    grid_z_mm: np.ndarray\n    grid_svr_um: np.ndarray\n\n\ndef voxel_downsample(points_m: np.ndarray, voxel_size_m: float) -> np.ndarray:\n    \"\"\"Downsample point cloud using 3D voxel grid centroids (matching pcl::VoxelGrid).\n\n    Uses fast 1D key-based grouping for O(N) performance on large point clouds.\n    \"\"\"\n    if len(points_m) == 0:\n        return points_m\n\n    min_pt = points_m.min(axis=0)\n    coords = np.floor((points_m - min_pt) / voxel_size_m).astype(np.int64)\n    max_c = coords.max(axis=0) + 1\n\n    stride_y = max_c[2]\n    stride_x = max_c[1] * stride_y\n    key = coords[:, 0] * stride_x + coords[:, 1] * stride_y + coords[:, 2]\n\n    _, inverse = np.unique(key, return_inverse=True)\n    counts = np.bincount(inverse)\n\n    downsampled = np.column_stack([\n        np.bincount(inverse, weights=points_m[:, dim]) / counts\n        for dim in range(3)\n    ])\n    return downsampled\n\n\ndef pca_align_plane(points_m: np.ndarray) -> tuple[np.ndarray, np.ndarray, np.ndarray]:\n    \"\"\"Align point cloud surface normal to +Z axis using PCA eigendecomposition (matching PCL PCA).\"\"\"\n    centroid = points_m.mean(axis=0)\n    centered = points_m - centroid\n    cov = (centered.T @ centered) / max(len(points_m), 1)\n\n    eigenvalues, eigenvectors = np.linalg.eigh(cov)\n    # Sort descending: column 0 is max variance (X), 1 is mid (Y), 2 is normal (Z)\n    order = np.argsort(eigenvalues)[::-1]\n    eig_vecs = eigenvectors[:, order]\n\n    # Ensure right-handed coordinate system\n    if np.linalg.det(eig_vecs) < 0:\n        eig_vecs[:, 2] = -eig_vecs[:, 2]\n\n    # Rotate points into plane coordinates (col 0 -> X, col 1 -> Y, col 2 -> Z)\n    rotated = centered @ eig_vecs\n\n    # Zero-center Z\n    z_mean = rotated[:, 2].mean()\n    rotated[:, 2] -= z_mean\n\n    return rotated, centroid, eig_vecs\n\n\ndef _crop_grid_boundaries(valid_mask: np.ndarray) -> tuple[int, int, int, int]:\n    \"\"\"Shave invalid boundary borders matching cropPointCloud in cloud_viewer.cpp.\n\n    Returns (y_begin, y_end, x_begin, x_end).\n    \"\"\"\n    missing_xy = (~valid_mask).T\n    dim_x, dim_y = missing_xy.shape\n\n    missing_data = np.zeros((dim_x, dim_y), dtype=np.uint8)\n    missing_data[missing_xy] = 1\n\n    seen = np.zeros((dim_x, dim_y), dtype=bool)\n    dr = [0, 1, 0, -1]\n    dc = [1, 0, -1, 0]\n    r, c, di = 0, 0, 0\n    order: list[tuple[int, int]] = []\n\n    for _ in range(dim_x * dim_y):\n        order.append((r, c))\n        seen[r, c] = True\n        cr = r + dr[di]\n        cc = c + dc[di]\n        if 0 <= cr < dim_x and 0 <= cc < dim_y and not seen[cr, cc]:\n            r, c = cr, cc\n        else:\n            di = (di + 1) % 4\n            r += dr[di]\n            c += dc[di]\n\n    for r, c in order:\n        if missing_data[r, c] == 1:\n            if r == 0 or r == dim_x - 1 or c == 0 or c == dim_y - 1:\n                missing_data[r, c] = 2\n            elif (\n                (r > 0 and missing_data[r - 1, c] == 2)\n                or (r < dim_x - 1 and missing_data[r + 1, c] == 2)\n                or (c > 0 and missing_data[r, c - 1] == 2)\n                or (c < dim_y - 1 and missing_data[r, c + 1] == 2)\n            ):\n                missing_data[r, c] = 2\n\n    x_begin, x_end = 0, dim_x\n    y_begin, y_end = 0, dim_y\n    changed = True\n    while changed:\n        changed = False\n        for x in range(x_begin, x_end):\n            if missing_data[x, y_begin] == 2:\n                y_begin += 1\n                changed = True\n                break\n        for y in range(y_begin, y_end):\n            if missing_data[x_end - 1, y] == 2:\n                x_end -= 1\n                changed = True\n                break\n        for x in range(x_begin, x_end):\n            if missing_data[x, y_end - 1] == 2:\n                y_end -= 1\n                changed = True\n                break\n        for y in range(y_begin, y_end):\n            if missing_data[x_begin, y] == 2:\n                x_begin += 1\n                changed = True\n                break\n\n    return y_begin, y_end, x_begin, x_end\n\n\ndef rasterize_elevation_grid(\n    rotated_pts_m: np.ndarray,\n    pitch_m: float,\n) -> tuple[np.ndarray, np.ndarray, float, float]:\n    \"\"\"Rasterize 3D points onto regular 2D elevation grid using bilinear scatter interpolation.\n\n    Matches createDenseGridPointCloud and cropPointCloud in cloud_viewer.cpp.\n    \"\"\"\n    min_x, min_y = float(rotated_pts_m[:, 0].min()), float(rotated_pts_m[:, 1].min())\n    max_x, max_y = float(rotated_pts_m[:, 0].max()), float(rotated_pts_m[:, 1].max())\n\n    steps_x = int(math.ceil((max_x - min_x) / pitch_m)) + 1\n    steps_y = int(math.ceil((max_y - min_y) / pitch_m)) + 1\n\n    inv_pitch = 1.0 / pitch_m\n    ux = (rotated_pts_m[:, 0] - min_x) * inv_pitch\n    uy = (rotated_pts_m[:, 1] - min_y) * inv_pitch\n\n    ix0 = np.clip(np.floor(ux).astype(np.int32), 0, steps_x - 2)\n    iy0 = np.clip(np.floor(uy).astype(np.int32), 0, steps_y - 2)\n    fx = np.clip(ux - ix0, 0.0, 1.0)\n    fy = np.clip(uy - iy0, 0.0, 1.0)\n\n    w00 = (1.0 - fx) * (1.0 - fy)\n    w10 = fx * (1.0 - fy)\n    w01 = (1.0 - fx) * fy\n    w11 = fx * fy\n\n    grid_sum_zw = np.zeros((steps_y, steps_x), dtype=np.float64)\n    grid_sum_w = np.zeros((steps_y, steps_x), dtype=np.float64)\n\n    z = rotated_pts_m[:, 2]\n    np.add.at(grid_sum_zw, (iy0, ix0), w00 * z)\n    np.add.at(grid_sum_w, (iy0, ix0), w00)\n\n    np.add.at(grid_sum_zw, (iy0, ix0 + 1), w10 * z)\n    np.add.at(grid_sum_w, (iy0, ix0 + 1), w10)\n\n    np.add.at(grid_sum_zw, (iy0 + 1, ix0), w01 * z)\n    np.add.at(grid_sum_w, (iy0 + 1, ix0), w01)\n\n    np.add.at(grid_sum_zw, (iy0 + 1, ix0 + 1), w11 * z)\n    np.add.at(grid_sum_w, (iy0 + 1, ix0 + 1), w11)\n\n    valid = grid_sum_w > 1e-5\n    grid_z = np.zeros((steps_y, steps_x), dtype=np.float64)\n    grid_z[valid] = grid_sum_zw[valid] / grid_sum_w[valid]\n    grid_z[~valid] = np.nan\n\n    # Shave outer missing boundaries (cropPointCloud)\n    y_begin, y_end, x_begin, x_end = _crop_grid_boundaries(valid)\n    grid_z = grid_z[y_begin:y_end, x_begin:x_end]\n    valid = valid[y_begin:y_end, x_begin:x_end]\n    origin_x = min_x + x_begin * pitch_m\n    origin_y = min_y + y_begin * pitch_m\n\n    # Fill interior holes (fillHolesInGrid: fast 4-connected 8-pass iterative propagation)\n    if np.any(~valid) and np.any(valid):\n        filled_z = grid_z.copy()\n        current_valid = valid.copy()\n        for _ in range(8):\n            if np.all(current_valid):\n                break\n            up = np.roll(filled_z, 1, axis=0)\n            down = np.roll(filled_z, -1, axis=0)\n            left = np.roll(filled_z, 1, axis=1)\n            right = np.roll(filled_z, -1, axis=1)\n\n            up_v = np.roll(current_valid, 1, axis=0)\n            down_v = np.roll(current_valid, -1, axis=0)\n            left_v = np.roll(current_valid, 1, axis=1)\n            right_v = np.roll(current_valid, -1, axis=1)\n\n            up_v[0, :] = False\n            down_v[-1, :] = False\n            left_v[:, 0] = False\n            right_v[:, -1] = False\n\n            sum_neighbors = (\n                np.where(up_v, up, 0.0)\n                + np.where(down_v, down, 0.0)\n                + np.where(left_v, left, 0.0)\n                + np.where(right_v, right, 0.0)\n            )\n            count_neighbors = (\n                up_v.astype(np.int32)\n                + down_v.astype(np.int32)\n                + left_v.astype(np.int32)\n                + right_v.astype(np.int32)\n            )\n\n            fill_mask = (~current_valid) & (count_neighbors > 0)\n            if not np.any(fill_mask):\n                break\n\n            filled_z[fill_mask] = sum_neighbors[fill_mask] / count_neighbors[fill_mask]\n            current_valid[fill_mask] = True\n\n        if np.any(~current_valid):\n            mean_z = np.nanmean(filled_z)\n            filled_z[~current_valid] = mean_z\n            current_valid[:] = True\n\n        grid_z = filled_z\n        valid = current_valid\n\n    return grid_z, valid, origin_x, origin_y\n\n\ndef iso_gaussian_filter_1d_kernel(cutoff_m: float, pitch_m: float) -> np.ndarray:\n    \"\"\"Generate normalized 1D Gaussian filter kernel per ISO 16610-61 (alpha=0.4697).\"\"\"\n    alpha = 0.4697\n    k_size = int(math.ceil(0.5 * cutoff_m / pitch_m)) * 2 + 1\n    half = (k_size - 1) // 2\n    x = np.arange(-half, half + 1, dtype=np.float64)\n    kernel = np.exp(-np.pi / (alpha**2) * ((x * pitch_m) / cutoff_m) ** 2)\n    return kernel / np.sum(kernel)\n\n\ndef _convolve1d_constant(arr: np.ndarray, k_1d: np.ndarray, axis: int) -> np.ndarray:\n    \"\"\"1D convolution matching scipy.ndimage.convolve1d with mode='constant', cval=0.0.\"\"\"\n    k_len = len(k_1d)\n    half = k_len // 2\n    k_rev = k_1d[::-1]\n    if axis == 1:\n        padded = np.pad(arr, ((0, 0), (half, half)), mode=\"constant\")\n        windows = sliding_window_view(padded, k_len, axis=1)\n        return np.tensordot(windows, k_rev, axes=(-1, 0))\n    else:\n        padded = np.pad(arr, ((half, half), (0, 0)), mode=\"constant\")\n        windows = sliding_window_view(padded, k_len, axis=0)\n        return np.tensordot(windows, k_rev, axes=(-1, 0))\n\n\ndef _normalized_convolve_2d(arr: np.ndarray, k_1d: np.ndarray) -> np.ndarray:\n    \"\"\"Separable 2D convolution with boundary partial-kernel normalization matching cloud_viewer.cpp.\"\"\"\n    ones = np.ones_like(arr)\n    # Pass 1: horizontal (X)\n    num = _convolve1d_constant(arr, k_1d, axis=1)\n    den = _convolve1d_constant(ones, k_1d, axis=1)\n    step1 = num / np.maximum(den, 1e-12)\n    # Pass 2: vertical (Y)\n    num = _convolve1d_constant(step1, k_1d, axis=0)\n    den = _convolve1d_constant(ones, k_1d, axis=0)\n    return num / np.maximum(den, 1e-12)\n\n\ndef apply_dual_pass_gaussian_filter(\n    grid_z_m: np.ndarray,\n    pitch_m: float,\n    short_cutoff_m: float,\n    long_cutoff_m: float,\n) -> np.ndarray:\n    \"\"\"Dual-pass separable areal Gaussian filtration per ASTM WK92969 / ISO 16610-61.\n\n    Matches filterShortLong in cloud_viewer.cpp:\n    Pass 1: Short wavelength low-pass (removes high-frequency scanner noise).\n    Pass 2: Long wavelength low-pass applied to z_short (extracts form/waviness).\n    Roughness profile: roughness_z = z_short - z_long.\n    \"\"\"\n    z_short = grid_z_m\n    if short_cutoff_m > 0:\n        k_short = iso_gaussian_filter_1d_kernel(short_cutoff_m, pitch_m)\n        z_short = _normalized_convolve_2d(grid_z_m, k_short)\n\n    if long_cutoff_m > 0:\n        k_long = iso_gaussian_filter_1d_kernel(long_cutoff_m, pitch_m)\n        z_long = _normalized_convolve_2d(z_short, k_long)\n        return z_short - z_long\n\n    return z_short\n\n\ndef _fft_convolve2d_same(in1: np.ndarray, in2: np.ndarray) -> np.ndarray:\n    \"\"\"2D FFT convolution matching scipy.signal.fftconvolve(..., mode='same').\"\"\"\n    s1 = in1.shape\n    s2 = in2.shape\n    shape = (s1[0] + s2[0] - 1, s1[1] + s2[1] - 1)\n    sp1 = np.fft.rfft2(in1, s=shape)\n    sp2 = np.fft.rfft2(in2, s=shape)\n    ret = np.fft.irfft2(sp1 * sp2, s=shape)\n    f0 = (s2[0] - 1) // 2\n    f1 = (s2[1] - 1) // 2\n    return ret[f0 : f0 + s1[0], f1 : f1 + s1[1]]\n\n\ndef compute_variogram_and_svr(\n    roughness_z_m: np.ndarray,\n    pitch_m: float,\n    points_on_var: int = 10,\n    span_m: float = 0.0005,\n) -> tuple[float, float, float, np.ndarray, np.ndarray, np.ndarray]:\n    \"\"\"Compute ASTM WK92969 Sa, Sq, Svr, variogram buckets, and local Svr grid.\n\n    Uses 2D FFT autocorrelation for O(1) pairwise displacement accumulation (~38 ms)\n    and 2D FFT convolution for the spatial Svr heatmap grid (~50 ms).\n    \"\"\"\n    height, width = roughness_z_m.shape\n\n    # Sa and Sq in micrometers\n    sa_um = float(np.mean(np.abs(roughness_z_m)) * 1e6)\n    sq_um = float(np.sqrt(np.mean(roughness_z_m**2)) * 1e6)\n\n    # Evaluation length parameter setup\n    max_ev_m = points_on_var * span_m\n    max_cells = int(math.ceil(max_ev_m / pitch_m))\n\n    z_um = roughness_z_m * 1e6\n    pad_h = height + max_cells + 1\n    pad_w = width + max_cells + 1\n\n    # Global Variogram via 2D FFT Autocorrelation\n    z_fft = np.fft.rfft2(z_um, s=(pad_h, pad_w))\n    autocorr = np.fft.irfft2(z_fft * np.conj(z_fft), s=(pad_h, pad_w))\n    integral_sq = np.pad(np.cumsum(np.cumsum(z_um**2, axis=0), axis=1), ((1, 0), (1, 0)))\n\n    var_sums = np.zeros(points_on_var, dtype=np.float64)\n    var_counts = np.zeros(points_on_var, dtype=np.int64)\n\n    for dy in range(max_cells + 1):\n        for dx in range(-max_cells, max_cells + 1):\n            if dy == 0 and dx <= 0:\n                continue\n            dist = math.sqrt((dx * pitch_m) ** 2 + (dy * pitch_m) ** 2)\n            b = int(math.floor(dist / span_m))\n            if b >= points_on_var:\n                continue\n\n            y_src0 = dy\n            y_src1 = height\n            x_src0 = max(0, dx)\n            x_src1 = min(width, width + dx)\n\n            y_dst0 = 0\n            y_dst1 = height - dy\n            x_dst0 = max(0, -dx)\n            x_dst1 = min(width, width - dx)\n\n            s1 = (\n                integral_sq[y_src1, x_src1]\n                - integral_sq[y_src0, x_src1]\n                - integral_sq[y_src1, x_src0]\n                + integral_sq[y_src0, x_src0]\n            )\n            s2 = (\n                integral_sq[y_dst1, x_dst1]\n                - integral_sq[y_dst0, x_dst1]\n                - integral_sq[y_dst1, x_dst0]\n                + integral_sq[y_dst0, x_dst0]\n            )\n\n            ac_col = dx if dx >= 0 else pad_w + dx\n            prod = autocorr[dy, ac_col]\n\n            diff_sq_sum = s1 + s2 - 2.0 * prod\n            n_pairs = (height - dy) * (width - abs(dx))\n\n            var_sums[b] += 2.0 * diff_sq_sum\n            var_counts[b] += 2 * n_pairs\n\n    var_bins_um = np.zeros(points_on_var, dtype=np.float64)\n    valid_bins = var_counts > 0\n    var_bins_um[valid_bins] = np.sqrt(var_sums[valid_bins] / (2.0 * var_counts[valid_bins]))\n\n    # Svr is mean of variogram bins (ASTM WK92969 & SurfInspect)\n    svr_um = float(np.mean(var_bins_um[valid_bins])) if np.any(valid_bins) else 0.0\n\n    # Local Svr Spatial Heatmap via 2D FFT Convolution\n    y_k, x_k = np.ogrid[-max_cells : max_cells + 1, -max_cells : max_cells + 1]\n    dist_k = np.sqrt((x_k * pitch_m) ** 2 + (y_k * pitch_m) ** 2)\n    kernel = ((dist_k <= max_ev_m) & (dist_k > 0)).astype(np.float64)\n\n    ones = np.ones_like(z_um)\n    w_local = _fft_convolve2d_same(ones, kernel)\n    conv_z = _fft_convolve2d_same(z_um, kernel)\n    conv_z2 = _fft_convolve2d_same(z_um**2, kernel)\n\n    pixel_sum_sq = w_local * (z_um**2) + conv_z2 - 2.0 * z_um * conv_z\n    pixel_sum_sq = np.maximum(pixel_sum_sq, 0.0)\n    grid_svr_um = np.sqrt(pixel_sum_sq / np.maximum(w_local, 1.0))\n\n    return sa_um, sq_um, svr_um, var_bins_um, var_counts, grid_svr_um\n\n\ndef analyze_pure_python(\n    points_xyz_mm: np.ndarray,\n    voxel_size_mm: float = 0.20,\n    short_cutoff_mm: float = 1.0,\n    long_cutoff_mm: float = 25.0,\n    variogram_points: int = 10,\n    variogram_span_mm: float = 0.5,\n    progress_callback = None,\n) -> PurePythonResult:\n    \"\"\"Execute the complete SurfInspect ASTM WK92969 analysis in 100% pure Python.\"\"\"\n    raw_pts = np.asarray(points_xyz_mm, dtype=np.float64)\n    if raw_pts.ndim != 2 or raw_pts.shape[1] != 3:\n        raise ValueError(\"Expected an Nx3 point array\")\n\n    finite_mask = np.isfinite(raw_pts).all(axis=1)\n    pts = raw_pts[finite_mask]\n    if len(pts) < 20:\n        raise ValueError(\"Requires at least 20 valid points\")\n\n    if progress_callback:\n        progress_callback(40, \"Filtering coordinate bounds...\")\n\n    # Step 1: Centering & Conversion to meters\n    centroid = pts.mean(axis=0)\n    pts_m = (pts - centroid) * 0.001\n    voxel_size_m = voxel_size_mm * 0.001\n    short_cutoff_m = short_cutoff_mm * 0.001\n    long_cutoff_m = long_cutoff_mm * 0.001\n    span_m = variogram_span_mm * 0.001\n\n    # Step 2: Voxel Grid Downsampling\n    if progress_callback:\n        progress_callback(50, \"Downsampling voxel grid...\")\n    downsampled_m = voxel_downsample(pts_m, voxel_size_m)\n\n    # Step 3: Form Removal via PCA Plane Fitting\n    if progress_callback:\n        progress_callback(62, \"Aligning surface plane...\")\n    rotated_m, _, _ = pca_align_plane(downsampled_m)\n\n    # Step 4: 2.5D Regular Elevation Grid Rasterization\n    if progress_callback:\n        progress_callback(72, \"Rasterizing elevation grid...\")\n    grid_z_m, valid_mask, origin_x_m, origin_y_m = rasterize_elevation_grid(rotated_m, voxel_size_m)\n\n    # Step 5: Dual-Pass ISO 16610-61 Gaussian Filtration\n    if progress_callback:\n        progress_callback(82, \"Applying Gaussian filtration...\")\n    roughness_z_m = apply_dual_pass_gaussian_filter(grid_z_m, voxel_size_m, short_cutoff_m, long_cutoff_m)\n\n    # Step 6: Variogram & Svr Metrology\n    if progress_callback:\n        progress_callback(90, \"Calculating variogram and Svr...\")\n    sa_um, sq_um, svr_um, var_bins_um, var_counts, grid_svr_um = compute_variogram_and_svr(\n        roughness_z_m,\n        voxel_size_m,\n        variogram_points,\n        span_m,\n    )\n\n    height, width = roughness_z_m.shape\n    grid_z_mm = roughness_z_m * 1000.0\n    surface_distances_mm = grid_z_mm.ravel()\n\n    return PurePythonResult(\n        sa_um=sa_um,\n        sq_um=sq_um,\n        svr_um=svr_um,\n        processed_points=len(downsampled_m),\n        variogram_bins_um=var_bins_um,\n        variogram_counts=var_counts,\n        surface_distances_mm=surface_distances_mm,\n        grid_width=width,\n        grid_height=height,\n        grid_origin_mm=np.array([origin_x_m * 1000.0, origin_y_m * 1000.0, voxel_size_mm], dtype=np.float64),\n        grid_z_mm=grid_z_mm,\n        grid_svr_um=grid_svr_um,\n    )\n\n", "svr_roughness/analyze.py": "from __future__ import annotations\n\nfrom collections.abc import Callable\nfrom dataclasses import fields, replace\nfrom pathlib import Path\nfrom typing import Any\n\nimport numpy as np\nimport numpy.typing as npt\n\nfrom ._display_grid import crop_points, fit_plane_basis\nfrom .algorithm import analyze_pure_python\nfrom .config import RoughnessConfig, coerce_range\nfrom .io import load_ascii_ply, load_points\nfrom .result import RoughnessGrid, RoughnessResult\n\n\ndef analyze_points(\n    points_xyz_mm: npt.ArrayLike,\n    config: RoughnessConfig | None = None,\n    progress: Callable[[str, float], None] | None = None,\n    **overrides: Any,\n) -> RoughnessResult:\n    \"\"\"Analyze an Nx3 XYZ point array using the native SurfInspect C++ core.\n\n    This is the canonical roughness path. File-specific APIs load data and\n    then delegate here to execute the native C++ numerical engine.\n\n    All heavy computation (gridding, Gaussian filtering, variogram) is\n    performed by the C++ core. Python only handles I/O, validation, and\n    packaging the result.\n    \"\"\"\n\n    resolved = _resolve_config(config, overrides)\n    if progress:\n        progress(\"Preparing point cloud\", 0.15)\n    points = np.asarray(points_xyz_mm, dtype=np.float64)\n    finite = np.isfinite(points).all(axis=1) if points.ndim == 2 else np.array([])\n    if points.ndim != 2 or points.shape[1] != 3:\n        raise ValueError(\"Expected an Nx3 point array\")\n    points = points[finite]\n    if len(points) < 3:\n        raise ValueError(\"Requires at least 3 valid points\")\n\n    selected = points\n    if resolved.x_range:\n        selected = selected[(selected[:, 0] >= resolved.x_range[0]) & (selected[:, 0] <= resolved.x_range[1])]\n    if resolved.y_range:\n        selected = selected[(selected[:, 1] >= resolved.y_range[0]) & (selected[:, 1] <= resolved.y_range[1])]\n    if resolved.z_range:\n        selected = selected[(selected[:, 2] >= resolved.z_range[0]) & (selected[:, 2] <= resolved.z_range[1])]\n    if resolved.percentile_crop > 0:\n        selection_plane = fit_plane_basis(selected)\n        _, crop_mask = crop_points(selection_plane.coords, resolved)\n        selected = selected[crop_mask]\n    if len(selected) < 20:\n        raise ValueError(\"SurfInspect engine requires at least 20 valid points\")\n\n    if progress:\n        progress(\"Executing ASTM WK92969 analysis\", 0.40)\n\n    # \u2500\u2500 Execute the pure-Python ASTM WK92969 numerical engine \u2500\u2500\n    pure_res = analyze_pure_python(\n        selected,\n        voxel_size_mm=resolved.grid_mm,\n        short_cutoff_mm=resolved.short_cutoff_mm,\n        long_cutoff_mm=resolved.long_cutoff_mm,\n        variogram_points=resolved.svr_points,\n        variogram_span_mm=resolved.svr_span_mm,\n    )\n\n    # \u2500\u2500 Plane fit for metadata \u2500\u2500\n    plane = fit_plane_basis(selected)\n\n    # \u2500\u2500 Package the raster elevation grid into RoughnessGrid \u2500\u2500\n    grid_z = pure_res.grid_z_mm\n    valid = ~np.isnan(grid_z)\n    grid = RoughnessGrid(\n        raw=grid_z,\n        filled=grid_z,\n        filtered=grid_z,\n        valid_raw=valid,\n        valid_filled=valid,\n        origin=pure_res.grid_origin_mm,\n        svr_map=pure_res.grid_svr_um,\n    )\n\n    if progress:\n        progress(\"Complete\", 1.0)\n    return RoughnessResult(\n        sa_um=pure_res.sa_um,\n        sq_um=pure_res.sq_um,\n        svr_um=pure_res.svr_um,\n        points=len(points),\n        cropped_points=pure_res.processed_points,\n        plane=plane,\n        raw_residual_std_mm=float(plane.coords[:, 2].std()),\n        raw_residual_p05_mm=float(np.percentile(plane.coords[:: max(1, len(plane.coords) // 50000), 2], 5)),\n        raw_residual_p95_mm=float(np.percentile(plane.coords[:: max(1, len(plane.coords) // 50000), 2], 95)),\n        grid=grid,\n        surface_distances_mm=pure_res.surface_distances_mm,\n        variogram_bins_um=pure_res.variogram_bins_um,\n        variogram_counts=pure_res.variogram_counts,\n        config=resolved,\n    )\n\n\ndef analyze_file(\n    path: str | Path,\n    config: RoughnessConfig | None = None,\n    progress: Callable[[str, float], None] | None = None,\n    **overrides: Any,\n) -> RoughnessResult:\n    if progress:\n        progress(\"Loading scan\", 0.05)\n    points = load_points(path)\n    return analyze_points(points, config, progress=progress, **overrides)\n\n\ndef analyze_ply(\n    path: str | Path,\n    config: RoughnessConfig | None = None,\n    progress: Callable[[str, float], None] | None = None,\n    **overrides: Any,\n) -> RoughnessResult:\n    return analyze_points(load_ascii_ply(path), config, progress=progress, **overrides)\n\n\n# Backward-compatible names from the first extraction.\ncompute_roughness = analyze_points\ncompute_roughness_from_ply = analyze_ply\n\n\ndef _resolve_config(config: RoughnessConfig | None, overrides: dict[str, Any]) -> RoughnessConfig:\n    base = config or RoughnessConfig()\n    if not overrides:\n        return base\n\n    allowed = {field.name for field in fields(RoughnessConfig)}\n    unknown = sorted(set(overrides) - allowed)\n    if unknown:\n        names = \", \".join(unknown)\n        raise TypeError(f\"Unknown roughness config override(s): {names}\")\n\n    normalized = dict(overrides)\n    for key in (\"x_range\", \"y_range\", \"z_range\"):\n        if key in normalized:\n            normalized[key] = coerce_range(normalized[key])\n    return replace(base, **normalized)\n", "svr_roughness/config.py": "from __future__ import annotations\n\nfrom collections.abc import Sequence\nfrom dataclasses import dataclass\n\nRange = tuple[float, float]\n\n\n@dataclass(frozen=True)\nclass RoughnessConfig:\n    \"\"\"Configuration for roughness analysis.\n\n    Input point coordinates are assumed to be millimeters. Roughness metrics are\n    reported in micrometers.\n\n    Default values match the canonical SurfInspect/PC_svr2 Settings.csv.\n    \"\"\"\n\n    grid_mm: float = 0.20\n    x_range: Range | None = None\n    y_range: Range | None = None\n    z_range: Range | None = None\n    percentile_crop: float = 0.0\n    min_points_per_cell: int = 1\n    max_hole_passes: int = 8\n    long_cutoff_mm: float = 25.0\n    short_cutoff_mm: float = 1.0\n    svr_points: int = 10\n    svr_span_mm: float = 0.5\n    mesh_resolution_mm: float = 1.0\n    mesh_smoothing_mm: float = 0.0\n    max_svr_points: int = 0\n    statistical_filter: bool = False\n    statistical_mean_k: int = 6\n    statistical_stddev: float = 3.0\n    # Select the recovered Cloud-Viewer PCA-aligned 1 mm Gaussian mesh path.\n    gaussian_mesh: bool = True\n\n    @classmethod\n    def surfinspect_defaults(cls) -> RoughnessConfig:\n        \"\"\"Return a config matching the canonical SurfInspect/PC_svr2 defaults.\"\"\"\n        return cls()\n\n    @classmethod\n    def astm_standard_defaults(cls) -> RoughnessConfig:\n        \"\"\"Return a config strictly enforcing the ASTM WK92969 standard parameters.\n\n        Note: Appendices X1.3, X2.3, and X3.3 of the draft standard contain a known\n        unit-conversion typo for cutoffs (0.001 mm and 0.025 mm). The values used\n        here match the intended 1 mm and 25 mm specified in Section 9.1.\n        \"\"\"\n        return cls(\n            grid_mm=0.20,\n            short_cutoff_mm=1.0,\n            long_cutoff_mm=25.0,\n            svr_span_mm=0.5,\n            svr_points=10,\n        )\n\n\ndef parse_range(text: str | None) -> Range | None:\n    if text is None:\n        return None\n    lo, hi = text.split(\":\", 1)\n    return float(lo), float(hi)\n\n\ndef coerce_range(value: str | Sequence[float] | None) -> Range | None:\n    if value is None:\n        return None\n    if isinstance(value, str):\n        return parse_range(value)\n    lo, hi = value\n    return float(lo), float(hi)\n\n\ndef config_from_values(\n    *,\n    grid_mm: float = 0.30,\n    x_range: str | Range | None = None,\n    y_range: str | Range | None = None,\n    z_range: str | Range | None = None,\n    percentile_crop: float = 0.0,\n    min_points_per_cell: int = 1,\n    max_hole_passes: int = 8,\n    long_cutoff_mm: float = 0.0,\n    short_cutoff_mm: float = 0.0,\n    svr_points: int = 1,\n    svr_span_mm: float = 0.5,\n    mesh_resolution_mm: float = 1.0,\n    max_svr_points: int = 0,\n    mesh_smoothing_mm: float = 0.0,\n    statistical_filter: bool = False,\n    statistical_mean_k: int = 6,\n    statistical_stddev: float = 3.0,\n    gaussian_mesh: bool = True,\n) -> RoughnessConfig:\n    return RoughnessConfig(\n        grid_mm=grid_mm,\n        x_range=coerce_range(x_range),\n        y_range=coerce_range(y_range),\n        z_range=coerce_range(z_range),\n        percentile_crop=percentile_crop,\n        min_points_per_cell=min_points_per_cell,\n        max_hole_passes=max_hole_passes,\n        long_cutoff_mm=long_cutoff_mm,\n        short_cutoff_mm=short_cutoff_mm,\n        svr_points=svr_points,\n        svr_span_mm=svr_span_mm,\n        mesh_resolution_mm=mesh_resolution_mm,\n        mesh_smoothing_mm=mesh_smoothing_mm,\n        max_svr_points=max_svr_points,\n        statistical_filter=statistical_filter,\n        statistical_mean_k=statistical_mean_k,\n        statistical_stddev=statistical_stddev,\n        gaussian_mesh=gaussian_mesh,\n    )\n", "svr_roughness/io.py": "from __future__ import annotations\n\nfrom pathlib import Path\nfrom typing import BinaryIO\n\nimport numpy as np\n\nfrom .result import FloatArray\n\n\ndef load_points(path: str | Path) -> FloatArray:\n    \"\"\"Load supported scan output into an Nx3 XYZ point array in source units.\n\n    The roughness engine expects millimeters. Most scanner PLY/PCD/STL outputs in\n    this repo are already millimeters; callers should scale before analysis if a\n    supplier uses another unit convention.\n    \"\"\"\n\n    source = Path(path)\n    suffix = source.suffix.lower()\n    if suffix == \".ply\":\n        return load_ply(source)\n    if suffix == \".pcd\":\n        return load_pcd(source)\n    if suffix == \".stl\":\n        return load_stl_vertices(source)\n    if suffix == \".obj\":\n        return load_obj(source)\n    if suffix in {\".csv\", \".xyz\", \".txt\", \".tsv\"}:\n        return load_delimited(source)\n    if suffix == \".npy\":\n        return _clean_loaded_points(np.load(source, allow_pickle=False))\n    if suffix == \".npz\":\n        with np.load(source, allow_pickle=False) as archive:\n            if not archive.files:\n                raise ValueError(\"NPZ file does not contain an array\")\n            return _clean_loaded_points(archive[archive.files[0]])\n    raise ValueError(f\"Unsupported point source type: {suffix}\")\n\n\ndef load_ply(path: str | Path) -> FloatArray:\n    with Path(path).open(\"rb\") as handle:\n        first = handle.readline().strip()\n        if first != b\"ply\":\n            raise ValueError(\"Not a PLY file\")\n\n        vertex_count = None\n        vertex_properties: list[str] = []\n        vertex_types: list[str] = []\n        in_vertex_element = False\n        data_format = \"\"\n        while True:\n            line = handle.readline()\n            if not line:\n                raise ValueError(\"PLY header ended before end_header\")\n            stripped = line.decode(\"ascii\", errors=\"replace\").strip()\n            if stripped.startswith(\"format \"):\n                parts = stripped.split()\n                if len(parts) >= 2:\n                    data_format = parts[1]\n            if stripped.startswith(\"element \"):\n                parts = stripped.split()\n                in_vertex_element = parts[1] == \"vertex\"\n                if in_vertex_element:\n                    vertex_count = int(parts[2])\n                    vertex_properties = []\n                    vertex_types = []\n            elif in_vertex_element and stripped.startswith(\"property \"):\n                parts = stripped.split()\n                if len(parts) == 3 and parts[1] != \"list\":\n                    vertex_types.append(parts[1])\n                    vertex_properties.append(parts[2])\n            elif stripped == \"end_header\":\n                break\n\n        if vertex_count is None:\n            raise ValueError(\"PLY vertex count not found\")\n        xyz_indexes = _xyz_field_indexes(vertex_properties)\n        if data_format == \"ascii\":\n            rows = np.loadtxt(handle, max_rows=vertex_count, usecols=xyz_indexes, dtype=np.float64)\n        elif data_format in (\"binary_little_endian\", \"binary_big_endian\"):\n            byte_order = \"<\" if data_format == \"binary_little_endian\" else \">\"\n            dtype = np.dtype(\n                [(name, _ply_numpy_dtype(type_name)) for name, type_name in zip(vertex_properties, vertex_types)]\n            ).newbyteorder(byte_order)\n            vertices = np.fromfile(handle, dtype=dtype, count=vertex_count)\n            rows = np.column_stack([vertices[vertex_properties[index]] for index in xyz_indexes])\n        else:\n            raise ValueError(f\"Unsupported PLY format: {data_format!r}\")\n\n    if rows.ndim == 1:\n        rows = rows.reshape(1, 3)\n    return _clean_loaded_points(rows)\n\n\nload_ascii_ply = load_ply\n\n\ndef load_delimited(path: str | Path) -> FloatArray:\n    suffix = Path(path).suffix.lower()\n    delimiter = \",\" if suffix == \".csv\" else \"\\t\" if suffix == \".tsv\" else None\n    try:\n        data = np.loadtxt(path, delimiter=delimiter, comments=\"#\", ndmin=2)\n    except ValueError as exc:\n        raise ValueError(f\"Could not read XYZ coordinates from {Path(path).name}\") from exc\n    if data.shape[1] < 3:\n        raise ValueError(\"Delimited point files must contain at least three columns\")\n    return _clean_loaded_points(data[:, :3])\n\n\ndef load_obj(path: str | Path) -> FloatArray:\n    vertices = []\n    for line in Path(path).read_text(encoding=\"utf-8\", errors=\"replace\").splitlines():\n        parts = line.strip().split()\n        if parts and parts[0] == \"v\" and len(parts) >= 4:\n            vertices.append((float(parts[1]), float(parts[2]), float(parts[3])))\n    if not vertices:\n        raise ValueError(\"No OBJ vertices were found\")\n    return _clean_loaded_points(np.asarray(vertices, dtype=np.float64))\n\n\ndef _ply_numpy_dtype(type_name: str) -> str:\n    dtype = {\n        \"char\": \"<i1\",\n        \"int8\": \"<i1\",\n        \"uchar\": \"<u1\",\n        \"uint8\": \"<u1\",\n        \"short\": \"<i2\",\n        \"int16\": \"<i2\",\n        \"ushort\": \"<u2\",\n        \"uint16\": \"<u2\",\n        \"int\": \"<i4\",\n        \"int32\": \"<i4\",\n        \"uint\": \"<u4\",\n        \"uint32\": \"<u4\",\n        \"float\": \"<f4\",\n        \"double\": \"<f8\",\n    }.get(type_name)\n    if dtype is None:\n        raise ValueError(f\"Unsupported PLY property type: {type_name}\")\n    return dtype\n\n\ndef load_pcd(path: str | Path) -> FloatArray:\n    with Path(path).open(\"rb\") as handle:\n        header, data_start = _read_pcd_header(handle)\n        fields = header[\"FIELDS\"].split()\n        points_count = int(header[\"POINTS\"])\n        data_mode = header.get(\"DATA\", \"\").lower()\n\n        handle.seek(data_start)\n        if data_mode == \"ascii\":\n            points = _read_ascii_pcd(handle, fields, points_count)\n        elif data_mode == \"binary\":\n            points = _read_binary_pcd(handle, header, fields, points_count)\n        else:\n            raise ValueError(f\"Unsupported PCD DATA mode: {header.get('DATA')}\")\n    return _clean_loaded_points(points)\n\n\ndef load_stl_vertices(path: str | Path) -> FloatArray:\n    raw = Path(path).read_bytes()\n    if _looks_like_binary_stl(raw):\n        vertices = _read_binary_stl_vertices(raw)\n    else:\n        vertices = _read_ascii_stl_vertices(raw.decode(\"utf-8\", errors=\"ignore\"))\n    return _clean_loaded_points(vertices)\n\n\ndef _read_pcd_header(handle: BinaryIO) -> tuple[dict[str, str], int]:\n    header: dict[str, str] = {}\n    while True:\n        line = handle.readline()\n        if not line:\n            raise ValueError(\"PCD header ended before DATA\")\n        decoded = line.decode(\"utf-8\", errors=\"replace\").strip()\n        if not decoded or decoded.startswith(\"#\"):\n            continue\n        key, _, value = decoded.partition(\" \")\n        header[key.upper()] = value.strip()\n        if key.upper() == \"DATA\":\n            return header, handle.tell()\n\n\ndef _read_ascii_pcd(handle: BinaryIO, fields: list[str], points_count: int) -> FloatArray:\n    xyz_indexes = _xyz_field_indexes(fields)\n    text = handle.read().decode(\"utf-8\", errors=\"replace\")\n    rows = []\n    for line in text.splitlines():\n        if not line.strip():\n            continue\n        values = line.split()\n        rows.append([float(values[index]) for index in xyz_indexes])\n        if len(rows) >= points_count:\n            break\n    return np.asarray(rows, dtype=np.float64)\n\n\ndef _read_binary_pcd(\n    handle: BinaryIO,\n    header: dict[str, str],\n    fields: list[str],\n    points_count: int,\n) -> FloatArray:\n    sizes = [int(value) for value in header[\"SIZE\"].split()]\n    types = header[\"TYPE\"].split()\n    counts = [int(value) for value in header.get(\"COUNT\", \" \".join([\"1\"] * len(fields))).split()]\n    dtype_fields = []\n\n    for field, size, type_code, count in zip(fields, sizes, types, counts):\n        dtype = _numpy_dtype(size, type_code)\n        shape = (count,) if count > 1 else ()\n        dtype_fields.append((field, dtype, shape))\n\n    dtype = np.dtype(dtype_fields)\n    data = np.frombuffer(handle.read(dtype.itemsize * points_count), dtype=dtype, count=points_count)\n    return np.column_stack([data[axis].astype(np.float64).reshape(points_count) for axis in (\"x\", \"y\", \"z\")])\n\n\ndef _xyz_field_indexes(fields: list[str]) -> list[int]:\n    lowered = [field.lower() for field in fields]\n    try:\n        return [lowered.index(axis) for axis in (\"x\", \"y\", \"z\")]\n    except ValueError as exc:\n        raise ValueError(\"The file must contain x, y, and z fields\") from exc\n\n\ndef _numpy_dtype(size: int, type_code: str) -> str:\n    if type_code == \"F\":\n        return {4: \"<f4\", 8: \"<f8\"}[size]\n    if type_code == \"I\":\n        return {1: \"<i1\", 2: \"<i2\", 4: \"<i4\", 8: \"<i8\"}[size]\n    if type_code == \"U\":\n        return {1: \"<u1\", 2: \"<u2\", 4: \"<u4\", 8: \"<u8\"}[size]\n    raise ValueError(f\"Unsupported PCD field type: {type_code}\")\n\n\ndef _looks_like_binary_stl(raw: bytes) -> bool:\n    if len(raw) < 84:\n        return False\n    triangle_count = int.from_bytes(raw[80:84], byteorder=\"little\", signed=False)\n    return 84 + triangle_count * 50 == len(raw)\n\n\ndef _read_binary_stl_vertices(raw: bytes) -> FloatArray:\n    triangle_count = int.from_bytes(raw[80:84], byteorder=\"little\", signed=False)\n    dtype = np.dtype(\n        [\n            (\"normal\", \"<f4\", (3,)),\n            (\"vertices\", \"<f4\", (3, 3)),\n            (\"attribute_byte_count\", \"<u2\"),\n        ]\n    )\n    triangles = np.frombuffer(raw, dtype=dtype, count=triangle_count, offset=84)\n    return triangles[\"vertices\"].reshape(-1, 3).astype(np.float64)\n\n\ndef _read_ascii_stl_vertices(text: str) -> FloatArray:\n    vertices = []\n    for line in text.splitlines():\n        stripped = line.strip()\n        if stripped.startswith(\"vertex \"):\n            _, x, y, z = stripped.split()\n            vertices.append((float(x), float(y), float(z)))\n    if not vertices:\n        raise ValueError(\"No STL vertices were found\")\n    return np.asarray(vertices, dtype=np.float64)\n\n\ndef _clean_loaded_points(points: FloatArray) -> FloatArray:\n    points = np.asarray(points, dtype=np.float64)\n    if points.ndim != 2 or points.shape[1] != 3:\n        raise ValueError(\"Expected an Nx3 point array\")\n    points = points[np.isfinite(points).all(axis=1)]\n    if len(points) < 3:\n        raise ValueError(\"Need at least 3 valid points\")\n    return points\n", "svr_roughness/result.py": "from __future__ import annotations\n\nimport json\nfrom dataclasses import dataclass\nfrom pathlib import Path\n\nimport numpy as np\nimport numpy.typing as npt\n\nfrom .config import RoughnessConfig\n\nFloatArray = npt.NDArray[np.float64]\nBoolArray = npt.NDArray[np.bool_]\nIntArray = npt.NDArray[np.int64]\n\n\n@dataclass(frozen=True)\nclass PlaneFit:\n    centroid: FloatArray\n    normal: FloatArray\n    x_axis: FloatArray\n    y_axis: FloatArray\n    coords: FloatArray\n\n\n@dataclass(frozen=True)\nclass RoughnessGrid:\n    raw: FloatArray\n    filled: FloatArray\n    filtered: FloatArray\n    valid_raw: BoolArray\n    valid_filled: BoolArray\n    origin: FloatArray\n    svr_map: FloatArray | None = None\n\n\n@dataclass(frozen=True)\nclass RoughnessResult:\n    sa_um: float\n    sq_um: float\n    svr_um: float\n    points: int\n    cropped_points: int\n    plane: PlaneFit\n    raw_residual_std_mm: float\n    raw_residual_p05_mm: float\n    raw_residual_p95_mm: float\n    grid: RoughnessGrid\n    surface_distances_mm: FloatArray\n    variogram_bins_um: FloatArray\n    variogram_counts: IntArray\n    config: RoughnessConfig\n\n    @property\n    def svr_mm(self) -> float:\n        \"\"\"S_VR in millimeters, as defined by ASTM WK92969 \u00a73.1.3.\"\"\"\n        return self.svr_um / 1000.0\n\n    @property\n    def svr_in(self) -> float:\n        \"\"\"S_VR in inches (1 mm = 0.0393701 in).\"\"\"\n        return self.svr_mm / 25.4\n\n    @property\n    def patch_width_mm(self) -> float:\n        \"\"\"Width of the surface patch along the fitted plane X-axis in mm.\"\"\"\n        return float(self.plane.coords[:, 0].max() - self.plane.coords[:, 0].min())\n\n    @property\n    def patch_height_mm(self) -> float:\n        \"\"\"Height of the surface patch along the fitted plane Y-axis in mm.\"\"\"\n        return float(self.plane.coords[:, 1].max() - self.plane.coords[:, 1].min())\n\n    @property\n    def patch_area_mm2(self) -> float:\n        \"\"\"Estimated surface area of the patch in mm\u00b2.\"\"\"\n        return self.patch_width_mm * self.patch_height_mm\n\n    @property\n    def point_density_pts_mm2(self) -> float:\n        \"\"\"Average point density of the raw cloud in points per mm\u00b2.\"\"\"\n        area = self.patch_area_mm2\n        return (self.points / area) if area > 0 else 0.0\n\n    @property\n    def average_point_spacing_mm(self) -> float:\n        \"\"\"Estimated average point spacing in mm.\"\"\"\n        density = self.point_density_pts_mm2\n        return float(1.0 / np.sqrt(density)) if density > 0 else 0.0\n\n    def comparator_equivalents(self) -> dict[str, str]:\n        \"\"\"Convert S_VR to approximate equivalent comparator visual grades per Appendices X1-X3.\n\n        ASTM WK92969 references:\n          - Appendix X1: GAR C-9 Cast Microfinish Comparator\n          - Appendix X2: SCRATA Standard (ASTM A802)\n          - Appendix X3: ACI Surface Indicator Scale\n        \"\"\"\n        svr = self.svr_mm\n\n        # SCRATA Comparator (A802) - Appendix X2\n        # A1: 0.0264 mm, A2: 0.0448 mm, A3: 0.0630 mm, A4: 0.1315 mm\n        if svr < 0.0214:\n            scrata = \"< A1 (Finer than 0.026 mm)\"\n        elif svr <= 0.0356:\n            scrata = \"A1 (Nominal ~0.026 mm)\"\n        elif svr <= 0.0539:\n            scrata = \"A2 (Nominal ~0.045 mm)\"\n        elif svr <= 0.0973:\n            scrata = \"A3 (Nominal ~0.063 mm)\"\n        elif svr <= 0.1500:\n            scrata = \"A4 (Nominal ~0.132 mm)\"\n        else:\n            scrata = \"> A4 (Rougher than 0.132 mm)\"\n\n        # GAR C-9 Comparator - Appendix X1\n        # 200: 0.0092, 300: 0.0163, 420: 0.0187, 560: 0.0274, 720: 0.0585, 900: 0.0711 mm\n        if svr < 0.0089:\n            gar = \"< C-9 200\"\n        elif svr <= 0.0128:\n            gar = \"C-9 200 (Nominal ~0.009 mm)\"\n        elif svr <= 0.0175:\n            gar = \"C-9 300 (Nominal ~0.016 mm)\"\n        elif svr <= 0.0231:\n            gar = \"C-9 420 (Nominal ~0.019 mm)\"\n        elif svr <= 0.0430:\n            gar = \"C-9 560 (Nominal ~0.027 mm)\"\n        elif svr <= 0.0648:\n            gar = \"C-9 720 (Nominal ~0.059 mm)\"\n        elif svr <= 0.0850:\n            gar = \"C-9 900 (Nominal ~0.071 mm)\"\n        else:\n            gar = \"> C-9 900\"\n\n        # ACI Surface Indicator Scale (SIS) - Appendix X3\n        # SIS-1: 0.0094, SIS-2: 0.0199, SIS-3: 0.0245, SIS-4: 0.0801 mm\n        if svr < 0.0088:\n            aci = \"< SIS-1\"\n        elif svr <= 0.0147:\n            aci = \"SIS-1 (Nominal ~0.009 mm)\"\n        elif svr <= 0.0222:\n            aci = \"SIS-2 (Nominal ~0.020 mm)\"\n        elif svr <= 0.0523:\n            aci = \"SIS-3 (Nominal ~0.025 mm)\"\n        elif svr <= 0.1000:\n            aci = \"SIS-4 (Nominal ~0.080 mm)\"\n        else:\n            aci = \"> SIS-4\"\n\n        return {\n            \"SCRATA (ASTM A802)\": scrata,\n            \"GAR C-9\": gar,\n            \"ACI SIS\": aci,\n        }\n\n    def metrics_dict(self) -> dict[str, float | int]:\n        return {\n            \"sa_um\": self.sa_um,\n            \"sq_um\": self.sq_um,\n            \"svr_um\": self.svr_um,\n            \"points\": self.points,\n            \"cropped_points\": self.cropped_points,\n            \"grid_width\": int(self.grid.raw.shape[1]),\n            \"grid_height\": int(self.grid.raw.shape[0]),\n            \"grid_pitch_mm\": float(self.config.grid_mm),\n            \"grid_coverage_raw_percent\": float(self.grid.valid_raw.mean() * 100.0),\n            \"grid_coverage_filled_percent\": float(self.grid.valid_filled.mean() * 100.0),\n            \"short_cutoff_mm\": float(self.config.short_cutoff_mm),\n            \"long_cutoff_mm\": float(self.config.long_cutoff_mm),\n            \"mesh_resolution_mm\": float(self.config.mesh_resolution_mm),\n            \"mesh_smoothing_mm\": float(self.config.mesh_smoothing_mm),\n            \"max_svr_points\": int(self.config.max_svr_points),\n        }\n\n    def save_metrics_json(self, path: str | Path) -> None:\n        save_metrics_json(self, path)\n\n    def save_grid_npz(self, path: str | Path) -> None:\n        save_grid_npz(self, path)\n\n\ndef save_grid_npz(result: RoughnessResult, path: str | Path) -> None:\n    Path(path).parent.mkdir(parents=True, exist_ok=True)\n    np.savez(\n        Path(path),\n        grid_raw=result.grid.raw,\n        grid_filled=result.grid.filled,\n        grid_filtered=result.grid.filtered,\n        valid_raw=result.grid.valid_raw,\n        valid_filled=result.grid.valid_filled,\n        grid_origin=result.grid.origin,\n        plane_centroid=result.plane.centroid,\n        plane_normal=result.plane.normal,\n        plane_x_axis=result.plane.x_axis,\n        plane_y_axis=result.plane.y_axis,\n    )\n\n\ndef save_metrics_json(result: RoughnessResult, path: str | Path) -> None:\n    metrics_path = Path(path)\n    metrics_path.parent.mkdir(parents=True, exist_ok=True)\n    metrics_path.write_text(json.dumps(result.metrics_dict(), indent=2) + \"\\n\")\n\n\ndef format_report(result: RoughnessResult, target_svr_mm: float | None = None) -> str:\n    \"\"\"Format a human-readable report per ASTM WK92969 \u00a710.\n\n    \u00a710.1 required fields:\n      - 10.1.1  Test result (S_VR)\n      - 10.1.2  Evaluation length\n      - 10.1.3  Distance bucket size\n      - 10.1.4  Cutoff wavelengths\n      - 10.1.5  Pre-processing parameters\n    \"\"\"\n    eval_length_mm = result.config.svr_points * result.config.svr_span_mm\n    patch_w = result.patch_width_mm\n    patch_h = result.patch_height_mm\n    density = result.point_density_pts_mm2\n    spacing = result.average_point_spacing_mm\n\n    # ASTM WK92969 \u00a73.1.5 recommendation: 50x50 mm or larger\n    patch_valid = patch_w >= 50.0 and patch_h >= 50.0\n    # ASTM WK92969 \u00a78.2 requirement: Point density of 0.2 mm or better required\n    density_valid = spacing <= 0.20\n\n    lines = [\n        \"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\",\n        \"  ASTM WK92969 Surface Variogram Roughness (S_VR) Report\",\n        \"\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\",\n        \"\",\n        \"\u00a710.1.1  Test Result\",\n        f\"  S_VR = {result.svr_mm:.4f} mm  ({result.svr_um:.3f} \u00b5m / {result.svr_in:.5f} in)\",\n        f\"  Sa   = {result.sa_um:.3f} \u00b5m\",\n        f\"  Sq   = {result.sq_um:.3f} \u00b5m\",\n    ]\n\n    if target_svr_mm is not None and target_svr_mm > 0:\n        passed = result.svr_mm <= target_svr_mm\n        status_str = \"PASS (Within specification)\" if passed else \"FAIL (Exceeds specification)\"\n        lines.extend(\n            [\n                f\"  Purchaser Spec Target: <= {target_svr_mm:.4f} mm\",\n                f\"  Status (\u00a75.3):        {status_str}\",\n            ]\n        )\n\n    lines.extend(\n        [\n            \"\",\n            \"\u00a710.1.2  Evaluation Length\",\n            f\"  {eval_length_mm:.1f} mm  ({result.config.svr_points} bins \u00d7 {result.config.svr_span_mm} mm)\",\n            \"\",\n            \"\u00a710.1.3  Distance Bucket Size\",\n            f\"  {result.config.svr_span_mm} mm\",\n            \"\",\n            \"\u00a710.1.4  Cutoff Wavelengths\",\n            f\"  Short (\u03bbs): {result.config.short_cutoff_mm:g} mm\",\n            f\"  Long  (\u03bbc): {result.config.long_cutoff_mm:g} mm\",\n            \"\",\n            \"\u00a710.1.5  Pre-processing Parameters\",\n            f\"  Downsampling:   {result.config.grid_mm} mm\",\n            f\"  Outlier filter: {f'ON (k={result.config.statistical_mean_k}, \u03c3={result.config.statistical_stddev})' if result.config.statistical_filter else 'OFF'}\",\n            f\"  Gaussian mesh:  {'ON (ISO 16610-61)' if result.config.gaussian_mesh else 'OFF'}\",\n            \"\",\n            \"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\",\n            \"  Surface Patch & Sensor Validation\",\n            \"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\",\n            f\"  Patch Dimensions (\u00a73.1.5): {patch_w:.1f} \u00d7 {patch_h:.1f} mm (Area: {result.patch_area_mm2:.0f} mm\u00b2)\",\n            f\"  Patch Size Status:         {'VALID (>= 50x50 mm)' if patch_valid else 'WARNING (< 50x50 mm recommended)'}\",\n            f\"  Raw Points:                {result.points:,}\",\n            f\"  Processed Points:          {result.cropped_points:,}\",\n            f\"  Avg Point Spacing (\u00a78.2):  {spacing:.3f} mm (~{density:.1f} pts/mm\u00b2)\",\n            f\"  Point Density Status:      {'VALID (<= 0.20 mm spacing)' if density_valid else 'WARNING (> 0.20 mm required)'}\",\n            \"  Scanner Accuracy (\u00a77.1):   Recommended < 0.076 mm (0.0030 in)\",\n            f\"  Grid:                      {result.grid.raw.shape[1]} \u00d7 {result.grid.raw.shape[0]} cells, pitch={result.config.grid_mm:.4f} mm\",\n            f\"  Grid Coverage:             {result.grid.valid_filled.mean() * 100:.1f}%\",\n            \"\",\n            \"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\",\n            \"  Visual Comparator Equivalents (Appendices X1-X3)\",\n            \"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\",\n        ]\n    )\n\n    for std_name, grade in result.comparator_equivalents().items():\n        lines.append(f\"  {std_name:<24}: {grade}\")\n\n    lines.extend(\n        [\n            \"\",\n            \"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\",\n            \"  Plane & Geometry Alignment\",\n            \"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\",\n            f\"  Plane centroid: {result.plane.centroid}\",\n            f\"  Plane normal:   {result.plane.normal}\",\n            (\n                f\"  Raw residual mm: \"\n                f\"std={result.raw_residual_std_mm:.6f} \"\n                f\"p05={result.raw_residual_p05_mm:.6f} \"\n                f\"p95={result.raw_residual_p95_mm:.6f}\"\n            ),\n            \"\",\n            \"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\",\n            \"  Variogram Bins (Evaluation Length 0 to 5.0 mm)\",\n            \"\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\u2500\",\n        ]\n    )\n    for idx, value in enumerate(result.variogram_bins_um):\n        lo = idx * result.config.svr_span_mm\n        hi = (idx + 1) * result.config.svr_span_mm\n        if np.isfinite(value):\n            lines.append(\n                f\"  {lo:.3f}\u2013{hi:.3f} mm: {value:.3f} \u00b5m ({value / 1000.0:.4f} mm)  pairs={result.variogram_counts[idx]}\"\n            )\n        else:\n            lines.append(f\"  {lo:.3f}\u2013{hi:.3f} mm: no pairs\")\n    return \"\\n\".join(lines)\n", "svr_roughness/roughness.py": "\"\"\"Backward-compatible native-backed roughness module layout.\"\"\"\n\nfrom .analyze import analyze_file, analyze_ply, analyze_points, compute_roughness, compute_roughness_from_ply\nfrom .config import RoughnessConfig, config_from_values, parse_range\nfrom .io import load_ascii_ply, load_delimited, load_obj, load_pcd, load_ply, load_points, load_stl_vertices\nfrom .result import (\n    PlaneFit,\n    RoughnessGrid,\n    RoughnessResult,\n    format_report,\n    save_grid_npz,\n    save_metrics_json,\n)\n\n__all__ = [\n    \"PlaneFit\",\n    \"RoughnessConfig\",\n    \"RoughnessGrid\",\n    \"RoughnessResult\",\n    \"analyze_file\",\n    \"analyze_ply\",\n    \"analyze_points\",\n    \"compute_roughness\",\n    \"compute_roughness_from_ply\",\n    \"config_from_values\",\n    \"format_report\",\n    \"load_ascii_ply\",\n    \"load_delimited\",\n    \"load_obj\",\n    \"load_pcd\",\n    \"load_ply\",\n    \"load_points\",\n    \"load_stl_vertices\",\n    \"parse_range\",\n    \"save_grid_npz\",\n    \"save_metrics_json\",\n]\n"};

self.reportProgress = function(percent, text) {
  self.postMessage({ type: "progress", percent: percent, text: text });
};

async function initPyodide() {
  try {
    postMessage({ type: "status", text: "Initializing..." });
    pyodide = await loadPyodide({
      indexURL: "https://cdn.jsdelivr.net/pyodide/v0.27.2/full/"
    });
    
    await pyodide.loadPackage("numpy");

    // Write pure-Python metrology core to virtual filesystem
    pyodide.FS.mkdirTree("/home/pyodide/svr_roughness");
    for (const [filePath, content] of Object.entries(PYTHON_FILES)) {
      pyodide.FS.writeFile("/home/pyodide/" + filePath, content);
    }

    // Setup Python execution environment
    pyodide.runPython(`
import sys
import io
import time
import json
import gzip
import zipfile
from pathlib import Path
import numpy as np
import js

def report(pct, text):
    try:
        js.reportProgress(pct, text)
    except Exception:
        pass

sys.path.insert(0, '/home/pyodide')
from svr_roughness.algorithm import analyze_pure_python
from svr_roughness.config import RoughnessConfig
from svr_roughness.io import load_points
from svr_roughness.result import format_report, RoughnessResult, RoughnessGrid, PlaneFit

def decompress_if_needed(raw_bytes, file_name):
    lower = file_name.lower()
    if raw_bytes.startswith(b"\\x1f\\x8b"):
        return gzip.decompress(raw_bytes), file_name[:-3] if lower.endswith(".gz") else file_name
    if raw_bytes.startswith(b"PK\\x03\\x04"):
        with zipfile.ZipFile(io.BytesIO(raw_bytes)) as zf:
            exts = {".ply", ".pcd", ".stl", ".obj", ".csv", ".tsv", ".xyz", ".txt", ".npy", ".npz"}
            candidates = [n for n in zf.namelist() if Path(n).suffix.lower() in exts and not Path(n).name.startswith(".")]
            if not candidates:
                raise ValueError("Zip archive contains no supported 3D scan files")
            return zf.read(candidates[0]), Path(candidates[0]).name
    return raw_bytes, file_name

def run_analysis_payload(file_path_str, file_name, grid_mm, short_cutoff_mm, long_cutoff_mm, gaussian_mesh):
    t0 = time.perf_counter()
    report(12, "Reading scan data...")
    path = Path(file_path_str)

    with path.open("rb") as f:
        head = f.read(4)

    if head.startswith(b"\\x1f\\x8b") or head.startswith(b"PK\\x03\\x04"):
        raw_bytes = path.read_bytes()
        file_bytes, eff_name = decompress_if_needed(raw_bytes, file_name)
        suffix = Path(eff_name).suffix.lower()
        scan_path = Path("/home/pyodide/temp_scan" + suffix)
        scan_path.write_bytes(file_bytes)
        if path.exists():
            path.unlink()
    else:
        scan_path = path
        eff_name = file_name

    t_decomp = time.perf_counter()
    report(24, "Parsing 3D coordinates...")
    try:
        pts = load_points(scan_path)
    finally:
        if scan_path.exists():
            scan_path.unlink()

    t_load = time.perf_counter()
    report(36, f"Downsampling {len(pts):,} points...")
    res = analyze_pure_python(
        pts,
        voxel_size_mm=grid_mm,
        short_cutoff_mm=short_cutoff_mm,
        long_cutoff_mm=long_cutoff_mm,
        variogram_points=10,
        variogram_span_mm=0.5,
        progress_callback=report,
    )
    t_analyze = time.perf_counter()

    report(92, "Aligning surface plane...")
    conf = RoughnessConfig(
        grid_mm=grid_mm,
        short_cutoff_mm=short_cutoff_mm,
        long_cutoff_mm=long_cutoff_mm,
        gaussian_mesh=gaussian_mesh,
    )
    
    centroid = pts.mean(axis=0)
    centered = pts - centroid
    cov = (centered.T @ centered) / max(len(pts) - 1, 1)
    _, eigvecs = np.linalg.eigh(cov)
    normal = eigvecs[:, 0]
    if normal[2] < 0: normal = -normal
    normal /= np.linalg.norm(normal)
    gx = np.array([1.0, 0.0, 0.0])
    x_ax = gx - normal * np.dot(gx, normal)
    if np.linalg.norm(x_ax) < 1e-6:
        x_ax = np.array([0.0, 1.0, 0.0]) - normal * normal[1]
    x_ax /= np.linalg.norm(x_ax)
    y_ax = np.cross(normal, x_ax)
    coords = np.column_stack((centered @ x_ax, centered @ y_ax, centered @ normal))
    plane = PlaneFit(centroid=centroid, normal=normal, x_axis=x_ax, y_axis=y_ax, coords=coords)

    r_grid = RoughnessGrid(
        raw=res.grid_z_mm,
        filled=res.grid_z_mm,
        filtered=res.grid_z_mm,
        valid_raw=~np.isnan(res.grid_z_mm),
        valid_filled=~np.isnan(res.grid_z_mm),
        origin=res.grid_origin_mm,
        svr_map=res.grid_svr_um,
    )

    report(95, "Formatting report...")
    full_res = RoughnessResult(
        sa_um=res.sa_um,
        sq_um=res.sq_um,
        svr_um=res.svr_um,
        points=len(pts),
        cropped_points=res.processed_points,
        plane=plane,
        raw_residual_std_mm=float(plane.coords[:, 2].std()),
        raw_residual_p05_mm=float(np.percentile(plane.coords[::max(1, len(plane.coords)//50000), 2], 5)),
        raw_residual_p95_mm=float(np.percentile(plane.coords[::max(1, len(plane.coords)//50000), 2], 95)),
        grid=r_grid,
        surface_distances_mm=res.surface_distances_mm,
        variogram_bins_um=res.variogram_bins_um,
        variogram_counts=res.variogram_counts,
        config=conf,
    )

    report_text = format_report(full_res)
    comparators = full_res.comparator_equivalents()

    patch_w = full_res.patch_width_mm
    patch_h = full_res.patch_height_mm
    avg_spacing = full_res.average_point_spacing_mm

    report(98, "Finalizing metrics...")
    out = {
        "sa_um": float(res.sa_um),
        "sq_um": float(res.sq_um),
        "svr_um": float(res.svr_um),
        "svr_mm": float(full_res.svr_mm),
        "svr_in": float(full_res.svr_in),
        "raw_points": int(len(pts)),
        "processed_points": int(res.processed_points),
        "patch_width_mm": float(patch_w),
        "patch_height_mm": float(patch_h),
        "average_point_spacing_mm": float(avg_spacing),
        "grid_coverage_pct": float(full_res.grid.valid_filled.mean() * 100.0),
        "grid_width": int(res.grid_width),
        "grid_height": int(res.grid_height),
        "origin_x": float(res.grid_origin_mm[0]),
        "origin_y": float(res.grid_origin_mm[1]),
        "pitch_mm": float(res.grid_origin_mm[2]),
        "grid_svr": res.grid_svr_um.tolist(),
        "var_bins": res.variogram_bins_um.tolist(),
        "var_counts": res.variogram_counts.tolist(),
        "comparators": comparators,
        "report_text": report_text,
        "effective_name": eff_name,
        "timings": {
            "decomp_ms": (t_decomp - t0) * 1000.0,
            "load_ms": (t_load - t_decomp) * 1000.0,
            "analyze_ms": (t_analyze - t_load) * 1000.0,
            "total_ms": (t_analyze - t0) * 1000.0,
        }
    }
    return json.dumps(out)
`);

    pyodideReady = true;
    postMessage({ type: "ready" });
  } catch (err) {
    postMessage({ type: "error", error: err.message || err.toString() });
  }
}

self.onmessage = async function(e) {
  const { type, payload } = e.data;
  if (type === "init") {
    if (!pyodideReady) await initPyodide();
    else postMessage({ type: "ready" });
  } else if (type === "analyze") {
    if (!pyodideReady) {
      await initPyodide();
    }
    try {
      const { fileData, fileName, grid_mm, short_cutoff_mm, long_cutoff_mm, gaussian_mesh } = payload;
      
      const ext = fileName.includes(".") ? "." + fileName.split(".").pop() : "";
      const uint8 = new Uint8Array(fileData);
      const filePath = "/home/pyodide/input_scan" + ext;
      pyodide.FS.writeFile(filePath, uint8);

      pyodide.globals.set("_file_path", filePath);
      pyodide.globals.set("_file_name", fileName);
      pyodide.globals.set("_grid_mm", grid_mm);
      pyodide.globals.set("_short_cutoff_mm", short_cutoff_mm);
      pyodide.globals.set("_long_cutoff_mm", long_cutoff_mm);
      pyodide.globals.set("_gaussian_mesh", gaussian_mesh);

      const jsonStr = pyodide.runPython(`
run_analysis_payload(_file_path, _file_name, _grid_mm, _short_cutoff_mm, _long_cutoff_mm, _gaussian_mesh)
`);
      const result = JSON.parse(jsonStr);
      postMessage({ type: "result", data: result });
    } catch (err) {
      postMessage({ type: "error", error: err.message || err.toString() });
    }
  }
};

initPyodide();
